  if any(x in cmd for x in ['time.Now','time.Since','time.Until','random.','uuid.V1','uuid.V4','crypto.Bcrypt','GenerateKey','EncryptAES','RSAEncrypt','net.Lookup','aws.','gcp.']):continue
